package emit

import (
	"strings"
	"testing"

	"github.com/phaenonlang/phaenon/internal/ast"
	"github.com/phaenonlang/phaenon/internal/lexer"
	"github.com/phaenonlang/phaenon/internal/parser"
)

func TestPrologue(t *testing.T) {
	cases := []struct {
		name, in, want string
	}{
		{
			"namespace first",
			"namespace App;\n\nfinal class A\n{\n}\n",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=1);\n\nnamespace App;\n\nfinal class A\n{\n}\n" +
				"// phaenon-map v1 A.phn 1-6=1 7:1\n",
		},
		{
			"empty file",
			"",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=1);\n// phaenon-map v1 A.phn 1-5=1\n",
		},
		{
			"own strict_types declare is kept, not duplicated",
			"declare(strict_types=0);\necho 1;\n",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=0);\necho 1;\n// phaenon-map v1 A.phn 1-4=1 5:1\n",
		},
		{
			"declare after a comment still counts",
			"// licence\ndeclare(strict_types=1);\n",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\n// licence\ndeclare(strict_types=1);\n// phaenon-map v1 A.phn 1-4=1 5:1\n",
		},
		{
			"a source that opens with a blank line gets no second one",
			"\necho 1;\n",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=1);\n\necho 1;\n// phaenon-map v1 A.phn 1-6=1 7:2\n",
		},
		{
			"no final line break: the map gets its own line",
			"echo 1;",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=1);\n\necho 1;\n// phaenon-map v1 A.phn 1-6=1 7:1\n",
		},
		{
			"__LINE__ is the source line",
			"echo __LINE__;\n\necho __line__;\n",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=1);\n\necho 1;\n\necho 3;\n// phaenon-map v1 A.phn 1-6=1 7:1\n",
		},
		{
			"__halt_compiler: the map goes before it, the data stays",
			"echo 1;\n__halt_compiler();\ndata\n",
			"<?php\n\n/* @generated by phaenon from A.phn */\n\ndeclare(strict_types=1);\n\necho 1;\n// phaenon-map v1 A.phn 1-6=1 7:1 8-8=1 9:2\n__halt_compiler();\ndata\n",
		},
	}
	for _, c := range cases {
		got, err := File([]byte(c.in), Options{SourceName: "src/A.phn", StrictTypes: true})
		if err != nil {
			t.Errorf("%s: %v", c.name, err)
			continue
		}
		if string(got) != c.want {
			t.Errorf("%s:\n got %q\nwant %q", c.name, got, c.want)
		}
		if !IsGenerated(got) {
			t.Errorf("%s: output not recognised as generated", c.name)
		}
	}
}

func TestNoStrictTypes(t *testing.T) {
	got, err := File([]byte("echo 1;\n"), Options{})
	if err != nil {
		t.Fatal(err)
	}
	// Without a source name there is no path to map to.
	if want := "<?php\n\n/* @generated by phaenon */\n\necho 1;\n"; string(got) != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestMapSource(t *testing.T) {
	got, err := File([]byte("echo 1;\n"), Options{SourceName: "src/A b.phn", MapSource: "../src/A b.phn"})
	if err != nil {
		t.Fatal(err)
	}
	if want := "// phaenon-map v1 ../src/A%20b.phn 1-4=1 5:1\n"; !strings.HasSuffix(string(got), want) {
		t.Errorf("got %q, want the map %q", got, want)
	}
	got, err = File([]byte("echo 1;\n"), Options{SourceName: "A.phn", NoMap: true})
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(got), "phaenon-map") {
		t.Errorf("NoMap wrote a map: %q", got)
	}
}

func TestIsGenerated(t *testing.T) {
	cases := map[string]bool{
		"<?php\n\n/* @generated by phaenon from A.phn */\n\necho 1;\n":          true,
		"<?php /* @generated by phaenon from A.phn */ declare(strict_types=1);": true, // before D19
		"<?php\n\necho 1; /* @generated by phaenon */\n":                        false,
		"<?php\n\n/* @generated by someone else */\n":                           false,
		"/* @generated by phaenon */":                                           false,
	}
	for in, want := range cases {
		if got := IsGenerated([]byte(in)); got != want {
			t.Errorf("%q: %v, want %v", in, got, want)
		}
	}
}

// TestBraces pins the PSR-12 placement of declaration braces and the
// layout of expression bodies on the edges the goldens do not show.
func TestBraces(t *testing.T) {
	cases := []struct{ name, in, want string }{
		{
			"a multi-line parameter list keeps `) {` together",
			"fun f(\n    int $a,\n) {\n    return;\n}\n",
			"function f(\n    int $a,\n) {\n    return;\n}\n",
		},
		{
			"a brace below a multi-line parameter list moves up",
			"fun f(\n    int $a,\n): int\n{\n    return $a;\n}\n",
			"function f(\n    int $a,\n): int {\n    return $a;\n}\n",
		},
		{
			"a brace on its own line stays",
			"fun f(): int\n{\n    return 1;\n}\n",
			"function f(): int\n{\n    return 1;\n}\n",
		},
		{
			"a comment before the brace keeps the layout",
			"fun f(): int /* why */ {\n    return 1;\n}\n",
			"function f(): int /* why */ {\n    return 1;\n}\n",
		},
		{
			"an empty class body",
			"interface I {}\n",
			"interface I\n{\n}\n",
		},
		{
			"an enum with a backing type",
			"enum E: string {\n    case A = 'a';\n}\n",
			"enum E: string\n{\n    case A = 'a';\n}\n",
		},
		{
			"closures and anonymous classes keep theirs",
			"$f = function () {\n    return new class {\n    };\n};\n",
			"$f = function () {\n    return new class {\n    };\n};\n",
		},
		{
			"a multi-line expression body moves in with its block",
			"fun f(): array => [\n    1,\n];\n",
			"function f(): array\n{\n    return [\n        1,\n    ];\n}\n",
		},
		{
			"a heredoc in an expression body keeps its lines",
			"fun f(): string => <<<TXT\n  a\n  TXT;\n",
			"function f(): string\n{\n    return <<<TXT\n  a\n  TXT;\n}\n",
		},
		{
			"tabs",
			"class A {\n\tfun f(): int => 1;\n}\n",
			"class A\n{\n\tpublic function f(): int\n\t{\n\t\treturn 1;\n\t}\n}\n",
		},
	}
	const header = "<?php\n\n/* @generated by phaenon */\n\n"
	for _, c := range cases {
		got, err := File([]byte(c.in), Options{})
		if err != nil {
			t.Errorf("%s: %v", c.name, err)
			continue
		}
		if want := header + c.want; string(got) != want {
			t.Errorf("%s:\n got %q\nwant %q", c.name, got, want)
		}
	}
}

func TestErrors(t *testing.T) {
	cases := map[string]string{
		"<?php\necho 1;":            "A.phn:1: Phaenon files do not start with <?php",
		"function f<T>(T $x): T {}": "A.phn:1: Phaenon syntax needs type information",
		"$y = $x is int;":           "A.phn:1: Phaenon syntax needs type information",
		"echo 1\necho 2;":           "A.phn:2: ",
	}
	for in, want := range cases {
		_, err := File([]byte(in), Options{SourceName: "A.phn"})
		if err == nil {
			t.Errorf("%q: expected an error", in)
			continue
		}
		if !strings.HasPrefix(err.Error(), want) {
			t.Errorf("%q: got %q, want prefix %q", in, err.Error(), want)
		}
	}
}

// TestInPlaceEditKeepsLineBreaks: an in-place edit stands for the lines of
// the span it replaces, so its text must have as many line breaks; text
// with lines of its own is a free edit.
func TestInPlaceEditKeepsLineBreaks(t *testing.T) {
	defer func() {
		if recover() == nil {
			t.Error("expected a panic for an in-place edit that changes the line count")
		}
	}()
	e := &emitter{src: []byte("a\nb\n")}
	e.replace(ast.Span{Start: 0, End: 2}, "x")
}

// TestFreeEditLines: the lines a free edit writes are holds of the line it
// starts on; the source line after them keeps its target.
func TestFreeEditLines(t *testing.T) {
	src := []byte("a;\nb;\n")
	f, err := parser.Parse(src, lexer.ModePhaenon)
	if err != nil {
		t.Fatal(err)
	}
	e := &emitter{src: src, throwsWritten: map[ast.Node]bool{}, opts: Options{SourceName: "A.phn"}}
	e.insertFree(3, "// one\n// two\n")
	e.prologue(f)
	out, _ := e.apply()
	want := "<?php\n\n/* @generated by phaenon from A.phn */\n\na;\n// one\n// two\nb;\n// phaenon-map v1 A.phn 1-4=1 5:1 6-7=2 8:2\n"
	if string(out) != want {
		t.Errorf("got %q\nwant %q", out, want)
	}
}
